 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find the solid divider that leaves two equally sized aligned panels.
    candidates = []
    for r, row in enumerate(grid):
        if 0 < r < h - 1 and len(set(row)) == 1:
            candidates.append((abs(r - (h - r - 1)), "row", r))
    for c in range(w):
        if 0 < c < w - 1 and len({grid[r][c] for r in range(h)}) == 1:
            candidates.append((abs(c - (w - c - 1)), "col", c))
    _, axis, divider = min(candidates)

    if axis == "row":
        first, second = grid[:divider], grid[divider + 1:]
    else:
        first = [row[:divider] for row in grid]
        second = [row[divider + 1:] for row in grid]

    shared = set(value for row in first for value in row) & set(
        value for row in second for value in row
    )
    overlap_color = next(iter(shared))
    output = [[overlap_color for _ in row] for row in first]
    for r in range(len(first)):
        for c in range(len(first[0])):
            if first[r][c] == overlap_color and second[r][c] == overlap_color:
                output[r][c] = 3
    return output
